<template><div class="page"><div class="header"><div><h1>评估历史</h1><p>查看历次岗位胜任力评估和能力变化</p></div><el-button @click="$router.push('/user')">返回用户中心</el-button></div><el-card><el-table :data="history" border stripe v-loading="loading"><el-table-column prop="assessmentId" label="评估编号"/><el-table-column prop="candidateName" label="候选人"/><el-table-column prop="jobName" label="目标岗位"/><el-table-column prop="score" label="综合得分"/><el-table-column prop="createdAt" label="评估时间"/><el-table-column label="状态"><template #default="{row}"><el-tag type="success">{{ row.status==='completed'?'已完成':row.status }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default><el-button link type="primary" @click="openDemo">查看演示报告</el-button></template></el-table-column></el-table></el-card></div></template>
<script setup>import { onMounted,ref } from "vue";import { useRouter } from "vue-router";import { getAssessmentHistory } from "@/api/assessment";import { useAssessmentStore } from "@/store/assessment";const history=ref([]);const loading=ref(false);const router=useRouter();const store=useAssessmentStore();onMounted(async()=>{loading.value=true;history.value=await getAssessmentHistory();loading.value=false});const openDemo=()=>{store.loadDemoAssessment();router.push('/report')};</script>
<style scoped>.page{min-height:100vh;padding:32px;background:#f5f7fa}.header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.header h1{margin:0}.header p{color:#909399}</style>
